/**
 * BUFF FPGA Inference — C-simulation testbench.
 *
 * Feeds golden test vectors (generated by export_conifer.py from the
 * Python reference solver) through buff_top() and compares outputs
 * against expected values within a quantization tolerance.
 *
 * Build & run:
 *   In Vitis HLS: csim_design
 *   Standalone:   g++ -std=c++14 -I$XILINX_HLS/include testbench.cpp buff_top.cpp -o tb && ./tb
 */

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <hls_stream.h>
#include "buff_top.h"
#include "buff_types.h"

// ── Golden test vectors ──────────────────────────────────────────────
// Generated by export_conifer.py.  Provides:
//   N_TEST_EVENTS
//   golden_input[N_TEST_EVENTS][N_FEATURES]   (quantized ap_fixed<16,6> values)
//   golden_output[N_TEST_EVENTS][N_FEATURES]  (Python reference outputs)
#include "golden_vectors.h"


int main() {
    int errors = 0;
    int total_checks = 0;
    float max_diff = 0.0f;

    printf("BUFF FPGA Testbench\n");
    printf("  N_FEATURES = %d\n", N_FEATURES);
    printf("  N_STEPS    = %d\n", N_STEPS);
    printf("  N_TREES    = %d\n", N_TREES);
    printf("  MAX_DEPTH  = %d\n", MAX_DEPTH);
    printf("  TOLERANCE  = %.4f\n", TOLERANCE);
    printf("  N_TEST_EVENTS = %d\n", N_TEST_EVENTS);
    printf("-----------------------------------\n");

    for (int ev = 0; ev < N_TEST_EVENTS; ev++) {
        // Feed input into stream
        hls::stream<data_t> in_stream("in");
        hls::stream<data_t> out_stream("out");

        for (int k = 0; k < N_FEATURES; k++) {
            in_stream.write(data_t(golden_input[ev][k]));
        }

        // Run inference
        buff_top(in_stream, out_stream);

        // Check outputs
        for (int k = 0; k < N_FEATURES; k++) {
            data_t got = out_stream.read();
            float got_f = float(got);
            float exp_f = golden_output[ev][k];
            float diff = fabsf(got_f - exp_f);

            if (diff > max_diff) {
                max_diff = diff;
            }

            total_checks++;

            if (diff > TOLERANCE) {
                errors++;
                printf("MISMATCH event=%d feat=%d: got=%.6f expected=%.6f diff=%.6f\n",
                       ev, k, got_f, exp_f, diff);
            }
        }
    }

    printf("-----------------------------------\n");
    printf("Total checks:  %d\n", total_checks);
    printf("Errors:        %d\n", errors);
    printf("Max diff:      %.6f\n", max_diff);
    printf("Result:        %s\n", errors == 0 ? "PASS" : "FAIL");

    return errors;
}
